runbook.code:
cd "$HOME/dev-opps-lab/app/taskboard"
export TASKBOARD_BASE_URL=http://127.0.0.1:18000
export LAB_ALICE_TOKEN=$(kubectl -n devopps get secret taskboard-env -o jsonpath='{.data.LAB_ALICE_TOKEN}' | base64 --decode)
export LAB_BOB_TOKEN=$(kubectl -n devopps get secret taskboard-env -o jsonpath='{.data.LAB_BOB_TOKEN}' | base64 --decode)
. .venv/bin/activate
python -m pytest tests/system -p no:cacheprovider --junitxml="$HOME/dev-opps-lab/evidence/w32-system.xml"
